20	import * as zrUtil from 'zrender/src/core/util';
21	import * as textContain from 'zrender/src/contain/text';
22	import {makeInner} from '../util/model';
23	import {
24	    makeLabelFormatter,
25	    getOptionCategoryInterval,
26	    shouldShowAllLabels
27	} from './axisHelper';
28	import Axis from './Axis';
29	import Model from '../model/Model';
30	import { AxisBaseOption, CategoryAxisBaseOption } from './axisCommonTypes';
31	import OrdinalScale from '../scale/Ordinal';
32	import { AxisBaseModel } from './AxisBaseModel';
33	import type Axis2D from './cartesian/Axis2D';
34	import { NullUndefined, ScaleTick, VisualAxisBreak } from '../util/types';
35	import { ScaleGetTicksOpt } from '../scale/Scale';
36	
37	
38	type AxisLabelInfoDetermined = {
39	    formattedLabel: string,
40	    rawLabel: string,
41	    tickValue: number,
42	    time: ScaleTick['time'] | NullUndefined,
43	    break: VisualAxisBreak | NullUndefined,
44	};
45	
46	type AxisCache<TKey, TVal> = {
47	    list: {key: TKey; value: TVal;}[]
48	};
49	
50	type AxisCategoryTickLabelCacheKey<TTickLabel extends AxisInnerStoreCacheProp> =
51	    CategoryAxisBaseOption[TTickLabel]['interval'];
52	
53	interface AxisCategoryLabelCreated {
54	    labels: AxisLabelInfoDetermined[]
55	    labelCategoryInterval: number
56	}
57	interface AxisCategoryTickCreated {
58	    ticks: number[]
59	    tickCategoryInterval?: number
60	}
61	
62	type AxisModelInnerStore = {
63	    lastAutoInterval: number
64	    lastTickCount: number
65	    axisExtent0: number
66	    axisExtent1: number
67	};
68	const modelInner = makeInner<AxisModelInnerStore, AxisBaseModel>();
69	
70	type AxisInnerStoreCacheProp = 'axisTick' | 'axisLabel';
71	type AxisInnerStore = {
72	    axisTick: AxisCache<AxisCategoryTickLabelCacheKey<'axisTick'>, AxisCategoryTickCreated>
73	    axisLabel: AxisCache<AxisCategoryTickLabelCacheKey<'axisLabel'>, AxisCategoryLabelCreated>
74	    autoInterval: number
75	};
76	const axisInner = makeInner<AxisInnerStore, Axis>();
77	
78	export const AxisTickLabelComputingKind = {
79	    estimate: 1,
80	    determine: 2,
81	} as const;
82	export type AxisTickLabelComputingKind =
83	    (typeof AxisTickLabelComputingKind)[keyof typeof AxisTickLabelComputingKind];
84	
85	export interface AxisLabelsComputingContext {
86	    // PENDING: ugly impl, refactor for better code structure?
87	    out: {
88	        // - If `noPxChangeTryDetermine` is not empty, it indicates that the result is not reusable
89	        //  when axis pixel extent or axis origin point changed.
90	        //  Generally the result is reusable if the result values are calculated with no dependency
91	        //  on pixel info, such as `axis.dataToCoord` or `axis.extent`.
92	        // - If ensuring no px changed, calling `noPxChangeTryDetermine` to attempt to convert the
93	        //  "estimate" result to "determine" result.
94	        //  If return any falsy, cannot make that conversion and need recompute.
95	        noPxChangeTryDetermine: (() => boolean)[]
96	    }
97	    // Must never be NullUndefined
98	    kind: AxisTickLabelComputingKind
99	}
100	
101	export function createAxisLabelsComputingContext(kind: AxisTickLabelComputingKind): AxisLabelsComputingContext {
102	    return {
103	        out: {
104	            noPxChangeTryDetermine: []
105	        },
106	        kind,
107	    };
108	}
109	
110	
111	function tickValuesToNumbers(axis: Axis, values: (number | string | Date)[]) {
112	    const nums = zrUtil.map(values, val => axis.scale.parse(val));
113	    if (axis.type === 'time' && nums.length > 0) {
114	        // Time axis needs duplicate first/last tick (see TimeScale.getTicks())
115	        // The first and last tick/label don't get drawn
116	        nums.sort();
117	        nums.unshift(nums[0]);
118	        nums.push(nums[nums.length - 1]);
119	    }
120	    return nums;
121	}
122	
123	export function createAxisLabels(axis: Axis, ctx: AxisLabelsComputingContext): {
124	    labels: AxisLabelInfoDetermined[]
125	} {
126	    const custom = axis.getLabelModel().get('customValues');
127	    if (custom) {
128	        const labelFormatter = makeLabelFormatter(axis);
129	        const extent = axis.scale.getExtent();
130	        const tickNumbers = tickValuesToNumbers(axis, custom);
131	        const ticks = zrUtil.filter(tickNumbers, val => val >= extent[0] && val <= extent[1]);
132	        return {
133	            labels: zrUtil.map(ticks, numval => {
134	                const tick = {value: numval};
135	                return {
136	                    formattedLabel: labelFormatter(tick),
137	                    rawLabel: axis.scale.getLabel(tick),
138	                    tickValue: numval,
139	                    time: undefined as ScaleTick['time'] | NullUndefined,
140	                    break: undefined as VisualAxisBreak | NullUndefined,
141	                };
142	            }),
143	        };
144	    }
145	    // Only ordinal scale support tick interval
146	    return axis.type === 'category'
147	        ? makeCategoryLabels(axis, ctx)
148	        : makeRealNumberLabels(axis);
149	}
150	
151	/**
152	 * @param tickModel For example, can be axisTick, splitLine, splitArea.
153	 */
154	export function createAxisTicks(
155	    axis: Axis,
156	    tickModel: AxisBaseModel,
157	    opt?: Pick<ScaleGetTicksOpt, 'breakTicks' | 'pruneByBreak'>
158	): {
159	    ticks: number[],
160	    tickCategoryInterval?: number
161	} {
162	    const custom = axis.getTickModel().get('customValues');
163	    if (custom) {
164	        const extent = axis.scale.getExtent();
165	        const tickNumbers = tickValuesToNumbers(axis, custom);
166	        return {
167	            ticks: zrUtil.filter(tickNumbers, val => val >= extent[0] && val <= extent[1])
168	        };
169	    }
170	    // Only ordinal scale support tick interval
171	    return axis.type === 'category'
172	        ? makeCategoryTicks(axis, tickModel)
173	        : {ticks: zrUtil.map(axis.scale.getTicks(opt), tick => tick.value)};
174	}
175	
176	function makeCategoryLabels(axis: Axis, ctx: AxisLabelsComputingContext): ReturnType<typeof createAxisLabels> {
177	    const labelModel = axis.getLabelModel();
178	    const result = makeCategoryLabelsActually(axis, labelModel, ctx);
179	
180	    return (!labelModel.get('show') || axis.scale.isBlank())
181	        ? {labels: []}
182	        : result;
183	}
184	
185	function makeCategoryLabelsActually(
186	    axis: Axis,
187	    labelModel: Model<AxisBaseOption['axisLabel']>,
188	    ctx: AxisLabelsComputingContext
189	): {
190	    labels: AxisLabelInfoDetermined[]
191	    labelCategoryInterval: number
192	} {
193	    const labelsCache = ensureCategoryLabelCache(axis);
194	    const optionLabelInterval = getOptionCategoryInterval(labelModel);
195	    const isEstimate = ctx.kind === AxisTickLabelComputingKind.estimate;
196	
197	    // In AxisTickLabelComputingKind.estimate, the result likely varies during a single
198	    // pass of ec main process,due to the change of axisExtent, and will not be shared with
199	    // splitLine. Therefore no cache is used.
200	    if (!isEstimate) {
201	        // PENDING: check necessary?
202	        const result = axisCacheGet(labelsCache, optionLabelInterval);
203	        if (result) {
204	            return result;
205	        }
206	    }
207	
208	    let labels;
209	    let numericLabelInterval;
210	
211	    if (zrUtil.isFunction(optionLabelInterval)) {
212	        labels = makeLabelsByCustomizedCategoryInterval(axis, optionLabelInterval);
213	    }
214	    else {
215	        numericLabelInterval = optionLabelInterval === 'auto'
216	            ? makeAutoCategoryInterval(axis, ctx) : optionLabelInterval;
217	        labels = makeLabelsByNumericCategoryInterval(axis, numericLabelInterval);
218	    }
219	
220	    const result = {labels, labelCategoryInterval: numericLabelInterval};
221	    if (!isEstimate) {
222	        axisCacheSet(labelsCache, optionLabelInterval, result);
223	    }
224	    else {
225	        ctx.out.noPxChangeTryDetermine.push(function () {
226	            axisCacheSet(labelsCache, optionLabelInterval, result);
227	            return true;
228	        });
229	    }
230	    return result;
231	}
232	
233	function makeCategoryTicks(axis: Axis, tickModel: AxisBaseModel) {
234	    const ticksCache = ensureCategoryTickCache(axis);
235	    const optionTickInterval = getOptionCategoryInterval(tickModel);
236	    const result = axisCacheGet(ticksCache, optionTickInterval);
237	
238	    if (result) {
239	        return result;
240	    }
241	
242	    let ticks: number[];
243	    let tickCategoryInterval;
244	
245	    // Optimize for the case that large category data and no label displayed,
246	    // we should not return all ticks.
247	    if (!tickModel.get('show') || axis.scale.isBlank()) {
248	        ticks = [];
249	    }
250	
251	    if (zrUtil.isFunction(optionTickInterval)) {
252	        ticks = makeLabelsByCustomizedCategoryInterval(axis, optionTickInterval, true);
253	    }
254	    // Always use label interval by default despite label show. Consider this
255	    // scenario, Use multiple grid with the xAxis sync, and only one xAxis shows
256	    // labels. `splitLine` and `axisTick` should be consistent in this case.
257	    else if (optionTickInterval === 'auto') {
258	        const labelsResult = makeCategoryLabelsActually(
259	            axis, axis.getLabelModel(), createAxisLabelsComputingContext(AxisTickLabelComputingKind.determine)
260	        );
261	        tickCategoryInterval = labelsResult.labelCategoryInterval;
262	        ticks = zrUtil.map(labelsResult.labels, function (labelItem) {
263	            return labelItem.tickValue;
264	        });
265	    }
266	    else {
267	        tickCategoryInterval = optionTickInterval;
268	        ticks = makeLabelsByNumericCategoryInterval(axis, tickCategoryInterval, true);
269	    }
270	
271	    // Cache to avoid calling interval function repeatedly.
272	    return axisCacheSet(ticksCache, optionTickInterval, {
273	        ticks: ticks, tickCategoryInterval: tickCategoryInterval
274	    });
275	}
276	
277	function makeRealNumberLabels(axis: Axis): ReturnType<typeof createAxisLabels> {
278	    const ticks = axis.scale.getTicks();
279	    const labelFormatter = makeLabelFormatter(axis);
280	    return {
281	        labels: zrUtil.map(ticks, function (tick, idx) {
282	            return {
283	                formattedLabel: labelFormatter(tick, idx),
284	                rawLabel: axis.scale.getLabel(tick),
285	                tickValue: tick.value,
286	                time: tick.time,
287	                break: tick.break,
288	            };
289	        })
290	    };
291	}
292	
293	// Large category data calculation is performance sensitive, and ticks and label probably will
294	// be fetched multiple times (e.g. shared by splitLine and axisTick). So we cache the result.
295	// axis is created each time during a ec process, so we do not need to clear cache.
296	const ensureCategoryTickCache = initAxisCacheMethod('axisTick');
297	const ensureCategoryLabelCache = initAxisCacheMethod('axisLabel');
298	
299	/**
300	 * PENDING: refactor to JS Map? Because key can be a function or more complicated object, and
301	 * cache size always is small, and currently no JS Map object key polyfill, we use a simple
302	 * array cache instead of plain object hash.
303	 */
304	function initAxisCacheMethod<TCacheProp extends AxisInnerStoreCacheProp>(prop: TCacheProp) {
305	    return function ensureCache(axis: Axis): AxisInnerStore[TCacheProp] {
306	        return axisInner(axis)[prop] || (axisInner(axis)[prop] = {list: []});
307	    };
308	}
309	
310	function axisCacheGet<TKey, TVal>(cache: AxisCache<TKey, TVal>, key: TKey): TVal | NullUndefined {
311	    for (let i = 0; i < cache.list.length; i++) {
312	        if (cache.list[i].key === key) {
313	            return cache.list[i].value;
314	        }
315	    }
316	}
317	
318	function axisCacheSet<TKey, TVal>(cache: AxisCache<TKey, TVal>, key: TKey, value: TVal): TVal {
319	    cache.list.push({key: key, value: value});
320	    return value;
321	}
322	
323	function makeAutoCategoryInterval(axis: Axis, ctx: AxisLabelsComputingContext): number {
324	    if (ctx.kind === AxisTickLabelComputingKind.estimate) {
325	        // Currently axisTick is not involved in estimate kind, and the result likely varies during a
326	        // single pass of ec main process, due to the change of axisExtent. Therefore no cache is used.
327	        const result = axis.calculateCategoryInterval(ctx);
328	        ctx.out.noPxChangeTryDetermine.push(function () {
329	            axisInner(axis).autoInterval = result;
330	            return true;
331	        });
332	        return result;
333	    }
334	    // Both tick and label uses this result, cacah it to avoid recompute.
335	    const result = axisInner(axis).autoInterval;
336	    return result != null
337	        ? result
338	        : (axisInner(axis).autoInterval = axis.calculateCategoryInterval(ctx));
339	}
340	
341	/**
342	 * Calculate interval for category axis ticks and labels.
343	 * Use a stretegy to try to avoid overlapping.
344	 * To get precise result, at least one of `getRotate` and `isHorizontal`
345	 * should be implemented in axis.
346	 */
347	export function calculateCategoryInterval(axis: Axis, ctx: AxisLabelsComputingContext) {
348	    const kind = ctx.kind;
349	
350	    const params = fetchAutoCategoryIntervalCalculationParams(axis);
351	    const labelFormatter = makeLabelFormatter(axis);
352	    const rotation = (params.axisRotate - params.labelRotate) / 180 * Math.PI;
353	
354	    const ordinalScale = axis.scale as OrdinalScale;
355	    const ordinalExtent = ordinalScale.getExtent();
356	    // Providing this method is for optimization:
357	    // avoid generating a long array by `getTicks`
358	    // in large category data case.
359	    const tickCount = ordinalScale.count();
360	
361	    if (ordinalExtent[1] - ordinalExtent[0] < 1) {
362	        return 0;
363	    }
364	
365	    let step = 1;
366	    // Simple optimization. Arbitrary value.
367	    const maxCount = 40;
368	    if (tickCount > maxCount) {
369	        step = Math.max(1, Math.floor(tickCount / maxCount));
370	    }
371	    let tickValue = ordinalExtent[0];
372	    const unitSpan = axis.dataToCoord(tickValue + 1) - axis.dataToCoord(tickValue);
373	    const unitW = Math.abs(unitSpan * Math.cos(rotation));
374	    const unitH = Math.abs(unitSpan * Math.sin(rotation));
375	
376	    let maxW = 0;
377	    let maxH = 0;
378	
379	    // Caution: Performance sensitive for large category data.
380	    // Consider dataZoom, we should make appropriate step to avoid O(n) loop.
381	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
382	        let width = 0;
383	        let height = 0;
384	
385	        // Not precise, do not consider align and vertical align
386	        // and each distance from axis line yet.
387	        const rect = textContain.getBoundingRect(
388	            labelFormatter({ value: tickValue }), params.font, 'center', 'top'
389	        );
390	        // Magic number
391	        width = rect.width * 1.3;
392	        height = rect.height * 1.3;
393	
394	        // Min size, void long loop.
395	        maxW = Math.max(maxW, width, 7);
396	        maxH = Math.max(maxH, height, 7);
397	    }
398	
399	    let dw = maxW / unitW;
400	    let dh = maxH / unitH;
401	    // 0/0 is NaN, 1/0 is Infinity.
402	    isNaN(dw) && (dw = Infinity);
403	    isNaN(dh) && (dh = Infinity);
404	    const interval = Math.max(0, Math.floor(Math.min(dw, dh)));
405	
406	    if (kind === AxisTickLabelComputingKind.estimate) {
407	        // In estimate kind, the inteval likely varies, thus do not erase the cache.
408	        ctx.out.noPxChangeTryDetermine.push(
409	            zrUtil.bind(calculateCategoryIntervalTryDetermine, null, axis, interval, tickCount)
410	        );
411	        return interval;
412	    }
413	
414	    const lastInterval = calculateCategoryIntervalDealCache(axis, interval, tickCount);
415	    return lastInterval != null ? lastInterval : interval;
416	}
417	
418	function calculateCategoryIntervalTryDetermine(
419	    axis: Axis, interval: number, tickCount: number
420	): boolean {
421	    return calculateCategoryIntervalDealCache(axis, interval, tickCount) == null;
422	}
423	
424	// Return the lastInterval if need to use it, otherwise return NullUndefined and save cache.
425	function calculateCategoryIntervalDealCache(
426	    axis: Axis, interval: number, tickCount: number
427	): number | NullUndefined {
428	    const cache = modelInner(axis.model);
429	    const axisExtent = axis.getExtent();
430	    const lastAutoInterval = cache.lastAutoInterval;
431	    const lastTickCount = cache.lastTickCount;
432	    // Use cache to keep interval stable while moving zoom window,
433	    // otherwise the calculated interval might jitter when the zoom
434	    // window size is close to the interval-changing size.
435	    // For example, if all of the axis labels are `a, b, c, d, e, f, g`.
436	    // The jitter will cause that sometimes the displayed labels are
437	    // `a, d, g` (interval: 2) sometimes `a, c, e`(interval: 1).
438	    if (lastAutoInterval != null
439	        && lastTickCount != null
440	        && Math.abs(lastAutoInterval - interval) <= 1
441	        && Math.abs(lastTickCount - tickCount) <= 1
442	        // Always choose the bigger one, otherwise the critical
443	        // point is not the same when zooming in or zooming out.
444	        && lastAutoInterval > interval
445	        // If the axis change is caused by chart resize, the cache should not
446	        // be used. Otherwise some hidden labels might not be shown again.
447	        && cache.axisExtent0 === axisExtent[0]
448	        && cache.axisExtent1 === axisExtent[1]
449	    ) {
450	        return lastAutoInterval;
451	    }
452	    // Only update cache if cache not used, otherwise the
453	    // changing of interval is too insensitive.
454	    else {
455	        cache.lastTickCount = tickCount;
456	        cache.lastAutoInterval = interval;
457	        cache.axisExtent0 = axisExtent[0];
458	        cache.axisExtent1 = axisExtent[1];
459	    }
460	}
461	
462	function fetchAutoCategoryIntervalCalculationParams(axis: Axis) {
463	    const labelModel = axis.getLabelModel();
464	    return {
465	        axisRotate: axis.getRotate
466	            ? axis.getRotate()
467	            : ((axis as Axis2D).isHorizontal && !(axis as Axis2D).isHorizontal())
468	            ? 90
469	            : 0,
470	        labelRotate: labelModel.get('rotate') || 0,
471	        font: labelModel.getFont()
472	    };
473	}
474	
475	function makeLabelsByNumericCategoryInterval(
476	    axis: Axis, categoryInterval: number
477	): AxisLabelInfoDetermined[];
478	function makeLabelsByNumericCategoryInterval(
479	    axis: Axis, categoryInterval: number, onlyTick: false
480	): AxisLabelInfoDetermined[];
481	function makeLabelsByNumericCategoryInterval(
482	    axis: Axis, categoryInterval: number, onlyTick: true
483	): number[];
484	function makeLabelsByNumericCategoryInterval(
485	    axis: Axis, categoryInterval: number, onlyTick?: boolean
486	) {
487	    const labelFormatter = makeLabelFormatter(axis);
488	    const ordinalScale = axis.scale as OrdinalScale;
489	    const ordinalExtent = ordinalScale.getExtent();
490	    const labelModel = axis.getLabelModel();
491	    const result: (AxisLabelInfoDetermined | number)[] = [];
492	
493	    // TODO: axisType: ordinalTime, pick the tick from each month/day/year/...
494	
495	    const step = Math.max((categoryInterval || 0) + 1, 1);
496	    let startTick = ordinalExtent[0];
497	    const tickCount = ordinalScale.count();
498	
499	    // Calculate start tick based on zero if possible to keep label consistent
500	    // while zooming and moving while interval > 0. Otherwise the selection
501	    // of displayable ticks and symbols probably keep changing.
502	    // 3 is empirical value.
503	    if (startTick !== 0 && step > 1 && tickCount / step > 2) {
504	        startTick = Math.round(Math.ceil(startTick / step) * step);
505	    }
506	
507	    // (1) Only add min max label here but leave overlap checking
508	    // to render stage, which also ensure the returned list
509	    // suitable for splitLine and splitArea rendering.
510	    // (2) Scales except category always contain min max label so
511	    // do not need to perform this process.
512	    const showAllLabel = shouldShowAllLabels(axis);
513	    const includeMinLabel = labelModel.get('showMinLabel') || showAllLabel;
514	    const includeMaxLabel = labelModel.get('showMaxLabel') || showAllLabel;
515	
516	    if (includeMinLabel && startTick !== ordinalExtent[0]) {
517	        addItem(ordinalExtent[0]);
518	    }
519	
520	    // Optimize: avoid generating large array by `ordinalScale.getTicks()`.
521	    let tickValue = startTick;
522	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
523	        addItem(tickValue);
524	    }
525	
526	    if (includeMaxLabel && tickValue - step !== ordinalExtent[1]) {
527	        addItem(ordinalExtent[1]);
528	    }
529	
530	    function addItem(tickValue: number) {
531	        const tickObj = { value: tickValue };
532	        result.push(onlyTick
533	            ? tickValue
534	            : {
535	                formattedLabel: labelFormatter(tickObj),
536	                rawLabel: ordinalScale.getLabel(tickObj),
537	                tickValue: tickValue,
538	                time: undefined,
539	                break: undefined,
540	            }
541	        );
542	    }
543	
544	    return result;
545	}
546	
547	type CategoryIntervalCb = (tickVal: number, rawLabel: string) => boolean;
548	
549	// When interval is function, the result `false` means ignore the tick.
550	// It is time consuming for large category data.
551	function makeLabelsByCustomizedCategoryInterval(
552	    axis: Axis, categoryInterval: CategoryIntervalCb
553	): AxisLabelInfoDetermined[];
554	function makeLabelsByCustomizedCategoryInterval(
555	    axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick: false
556	): AxisLabelInfoDetermined[];
557	function makeLabelsByCustomizedCategoryInterval(
558	    axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick: true
559	): number[];
560	function makeLabelsByCustomizedCategoryInterval(
561	    axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick?: boolean
562	) {
563	    const ordinalScale = axis.scale;
564	    const labelFormatter = makeLabelFormatter(axis);
565	    const result: (AxisLabelInfoDetermined | number)[] = [];
566	
567	    zrUtil.each(ordinalScale.getTicks(), function (tick) {
568	        const rawLabel = ordinalScale.getLabel(tick);
569	        const tickValue = tick.value;
570	        if (categoryInterval(tick.value, rawLabel)) {
571	            result.push(
572	                onlyTick
573	                ? tickValue
574	                : {
575	                    formattedLabel: labelFormatter(tick),
576	                    rawLabel: rawLabel,
577	                    tickValue: tickValue,
578	                    time: undefined,
579	                    break: undefined,
580	                }
581	            );
582	        }
583	    });
584	
585	    return result;
586	}
