import { createChart, getECModel } from '../../core/utHelper';
import { EChartsType } from '@/src/echarts';
import CartesianAxisModel from '@/src/coord/cartesian/AxisModel';


describe('axisTickLabelBuilder', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function getXAxis(): CartesianAxisModel['axis'] {
        return (getECModel(chart).getComponent('xAxis', 0) as CartesianAxisModel).axis;
    }

    describe('axisLabel_customValues_formatter_index', function () {

        it('index_is_the_position_in_the_filtered_label_list', function () {
            const calls: [number, number][] = [];
            chart.setOption({
                xAxis: {
                    type: 'value',
                    min: 0,
                    max: 10,
                    axisLabel: {
                        // `-5` and `20` are out of the axis extent and must not consume an index.
                        // `3` is repeated and each occurrence must keep its own index.
                        customValues: [-5, 1, 3, 3, 7, 20],
                        formatter: function (value: number, index: number) {
                            calls.push([value, index]);
                            return index + ':' + value;
                        }
                    }
                },
                yAxis: { type: 'value' },
                series: [{ type: 'line', data: [[1, 1], [7, 7]] }]
            });

            const axis = getXAxis();
            calls.length = 0;
            const labels = axis.getViewLabels();

            expect(labels.map(item => item.tickValue)).toEqual([1, 3, 3, 7]);
            expect(calls).toEqual([[1, 0], [3, 1], [3, 2], [7, 3]]);
            expect(labels.map(item => item.formattedLabel)).toEqual(
                ['0:1', '1:3', '2:3', '3:7']
            );
            expect(labels.map(item => item.rawLabel)).toEqual(['1', '3', '3', '7']);
        });

        it('index_of_normal_labels_is_not_changed', function () {
            const calls: [number, number][] = [];
            chart.setOption({
                xAxis: {
                    type: 'value',
                    min: 0,
                    max: 10,
                    splitNumber: 5,
                    axisLabel: {
                        formatter: function (value: number, index: number) {
                            calls.push([value, index]);
                            return index + ':' + value;
                        }
                    }
                },
                yAxis: { type: 'value' },
                series: [{ type: 'line', data: [[1, 1], [7, 7]] }]
            });

            const axis = getXAxis();
            calls.length = 0;
            const labels = axis.getViewLabels();

            expect(calls).toEqual([[0, 0], [2, 1], [4, 2], [6, 3], [8, 4], [10, 5]]);
            expect(labels.map(item => item.formattedLabel)).toEqual(
                ['0:0', '1:2', '2:4', '3:6', '4:8', '5:10']
